-- LUMEN core schema. Applied to project lavhnyodtacrjrcbyymj during initial setup.
create extension if not exists pgcrypto;
create schema if not exists private;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null check (username ~ '^[a-zA-Z0-9_]{3,24}$'), full_name text not null default 'Student', email text not null, avatar_url text, role text not null default 'student' check (role in ('student','operator')), class_grade text not null default '12', stream text not null default 'PCM', school_target text, timezone text not null default 'Asia/Kolkata', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.wallets (user_id uuid primary key references public.profiles(id) on delete cascade, coins bigint not null default 1000 check (coins >= 0), cash bigint not null default 50 check (cash >= 0), updated_at timestamptz not null default now());
create table public.chapter_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, subject_id text not null, chapter_id text not null, step_id text not null, completed boolean not null default false, completed_at timestamptz, updated_at timestamptz not null default now(), unique(user_id,subject_id,chapter_id,step_id));
create table public.focus_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, subject text, mode text not null default 'pomodoro' check(mode in ('pomodoro','deep_sprint','extreme_grind','stopwatch')), duration_minutes integer not null check(duration_minutes between 1 and 600), started_at timestamptz not null, ended_at timestamptz not null, xp_earned integer not null default 0 check(xp_earned>=0), coins_earned integer not null default 0 check(coins_earned>=0), completed boolean not null default true, created_at timestamptz not null default now(), check(ended_at>=started_at));
create table public.planner_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null check(length(trim(title)) between 1 and 180), subject text, priority text not null default 'P2' check(priority in ('P1','P2','P3')), estimated_minutes integer not null default 25 check(estimated_minutes between 1 and 600), study_day date not null default ((now() at time zone 'Asia/Kolkata' - interval '4 hours')::date), completed boolean not null default false, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.exams (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null, subject text not null, exam_date timestamptz not null, max_marks integer check(max_marks is null or max_marks>0), obtained_marks integer check(obtained_marks is null or obtained_marks>=0), created_at timestamptz not null default now(), check(max_marks is null or obtained_marks is null or obtained_marks<=max_marks));
create table public.vehicles (id text primary key, name text not null, maker text not null, tier text not null check(tier in ('Hypercar','Track Toy','Luxury GT','Concept Prototype','Le Mans Legend')), rarity text not null default 'Common' check(rarity in ('Common','Rare','Exotic','Mythic','1-of-1')), image_url text, top_speed_kmh integer, zero_to_100 numeric(4,2), horsepower integer, price_coins bigint not null default 0 check(price_coins>=0), price_cash bigint not null default 0 check(price_cash>=0), stock_limit integer, stock_sold integer not null default 0, is_limited boolean not null default false, is_operator_drop boolean not null default false, is_available boolean not null default true, release_at timestamptz, created_at timestamptz not null default now(), check(stock_limit is null or stock_sold<=stock_limit));
create table public.vehicles_owned (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, vehicle_id text not null references public.vehicles(id) on delete restrict, purchased_at timestamptz not null default now(), is_favorite boolean not null default false, custom_plate text, unique(user_id,vehicle_id));
create table public.wallet_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, currency text not null check(currency in ('coins','cash')), amount bigint not null check(amount<>0), reason text not null, source text not null default 'system', created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
create table public.broadcasts (id uuid primary key default gen_random_uuid(), title text not null, message text not null, kind text not null default 'info' check(kind in ('info','exam','urgent','maintenance')), starts_at timestamptz not null default now(), ends_at timestamptz, is_published boolean not null default false, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.activity_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, event_type text not null, title text not null, detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index chapter_progress_user_idx on public.chapter_progress(user_id);
create index focus_sessions_user_started_idx on public.focus_sessions(user_id,started_at desc);
create index planner_tasks_user_day_idx on public.planner_tasks(user_id,study_day);
create index exams_user_date_idx on public.exams(user_id,exam_date);
create index activity_events_user_created_idx on public.activity_events(user_id,created_at desc);
create index wallet_transactions_user_created_idx on public.wallet_transactions(user_id,created_at desc);
create index broadcasts_published_idx on public.broadcasts(is_published,starts_at desc);
create or replace function public.is_operator() returns boolean language sql stable security definer set search_path='' as $$ select (coalesce((auth.jwt()->>'email')='astryxleo@gmail.com' and coalesce((auth.jwt()->>'email_verified')::boolean,false),false) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='operator')); $$;
revoke all on function public.is_operator() from public; grant execute on function public.is_operator() to authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
declare chosen_username text; chosen_name text;
begin
 chosen_name:=coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),nullif(trim(new.raw_user_meta_data->>'name'),''),split_part(coalesce(new.email,'student'),'@',1),'Student');
 chosen_username:=lower(regexp_replace(coalesce(new.raw_user_meta_data->>'username',split_part(coalesce(new.email,'student'),'@',1)),'[^a-zA-Z0-9_]','','g'));
 chosen_username:=left(chosen_username,18);
 if length(chosen_username)<3 then chosen_username:='student'||substr(replace(new.id::text,'-',''),1,6); end if;
 if exists(select 1 from public.profiles p where p.username=chosen_username) then chosen_username:=left(chosen_username,15)||substr(replace(new.id::text,'-',''),1,6); end if;
 insert into public.profiles(id,username,full_name,email,role) values(new.id,chosen_username,chosen_name,coalesce(new.email,''),'student') on conflict(id) do nothing;
 insert into public.wallets(user_id) values(new.id) on conflict(user_id) do nothing; return new;
end; $$;
drop trigger if exists on_auth_user_created_lumen on auth.users;
create trigger on_auth_user_created_lumen after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create trigger profiles_touch_updated before update on public.profiles for each row execute procedure public.touch_updated_at();
create trigger wallets_touch_updated before update on public.wallets for each row execute procedure public.touch_updated_at();
create trigger planner_tasks_touch_updated before update on public.planner_tasks for each row execute procedure public.touch_updated_at();
alter table public.profiles enable row level security; alter table public.wallets enable row level security; alter table public.chapter_progress enable row level security; alter table public.focus_sessions enable row level security; alter table public.planner_tasks enable row level security; alter table public.exams enable row level security; alter table public.vehicles enable row level security; alter table public.vehicles_owned enable row level security; alter table public.wallet_transactions enable row level security; alter table public.broadcasts enable row level security; alter table public.activity_events enable row level security;
create policy "profiles read self or operator" on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_operator());
create policy "profiles insert self as student" on public.profiles for insert to authenticated with check(id=(select auth.uid()) and role='student');
create policy "profiles update self safe" on public.profiles for update to authenticated using(id=(select auth.uid()) or public.is_operator()) with check((id=(select auth.uid()) and role='student') or public.is_operator());
create policy "wallet read self or operator" on public.wallets for select to authenticated using(user_id=(select auth.uid()) or public.is_operator());
create policy "wallet operator update only" on public.wallets for update to authenticated using(public.is_operator()) with check(public.is_operator());
create policy "progress own all" on public.chapter_progress for all to authenticated using(user_id=(select auth.uid()) or public.is_operator()) with check(user_id=(select auth.uid()) or public.is_operator());
create policy "focus own read insert" on public.focus_sessions for select to authenticated using(user_id=(select auth.uid()) or public.is_operator());
create policy "focus insert own" on public.focus_sessions for insert to authenticated with check(user_id=(select auth.uid()));
create policy "planner own all" on public.planner_tasks for all to authenticated using(user_id=(select auth.uid()) or public.is_operator()) with check(user_id=(select auth.uid()) or public.is_operator());
create policy "exams own all" on public.exams for all to authenticated using(user_id=(select auth.uid()) or public.is_operator()) with check(user_id=(select auth.uid()) or public.is_operator());
create policy "vehicles catalog read" on public.vehicles for select to authenticated using(is_available or public.is_operator());
create policy "vehicles operator manage" on public.vehicles for all to authenticated using(public.is_operator()) with check(public.is_operator());
create policy "owned vehicles own all" on public.vehicles_owned for all to authenticated using(user_id=(select auth.uid()) or public.is_operator()) with check(user_id=(select auth.uid()) or public.is_operator());
create policy "transactions own read" on public.wallet_transactions for select to authenticated using(user_id=(select auth.uid()) or public.is_operator());
create policy "transactions operator insert" on public.wallet_transactions for insert to authenticated with check(public.is_operator());
create policy "broadcasts published read" on public.broadcasts for select to authenticated using((is_published and starts_at<=now() and (ends_at is null or ends_at>now())) or public.is_operator());
create policy "broadcasts operator manage" on public.broadcasts for all to authenticated using(public.is_operator()) with check(public.is_operator());
create policy "activity own read insert" on public.activity_events for all to authenticated using(user_id=(select auth.uid()) or public.is_operator()) with check(user_id=(select auth.uid()) or public.is_operator());
grant usage on schema public to authenticated;
grant select,insert,update on public.profiles to authenticated;
grant select,update on public.wallets to authenticated;
grant select,insert,update,delete on public.chapter_progress to authenticated;
grant select,insert on public.focus_sessions to authenticated;
grant select,insert,update,delete on public.planner_tasks to authenticated;
grant select,insert,update,delete on public.exams to authenticated;
grant select,insert,update,delete on public.vehicles to authenticated;
grant select,insert,update,delete on public.vehicles_owned to authenticated;
grant select on public.wallet_transactions to authenticated;
grant select,insert,update,delete on public.broadcasts to authenticated;
grant select,insert on public.activity_events to authenticated;
create or replace function public.operator_adjust_wallet(target_user uuid,currency_name text,delta bigint,reason_text text) returns void language plpgsql security definer set search_path='' as $$
begin
 if not public.is_operator() then raise exception 'operator access required'; end if;
 if currency_name not in ('coins','cash') or delta=0 then raise exception 'invalid adjustment'; end if;
 if length(trim(reason_text))<3 then raise exception 'reason required'; end if;
 update public.wallets set coins=case when currency_name='coins' then coins+delta else coins end,cash=case when currency_name='cash' then cash+delta else cash end
 where user_id=target_user and (case when currency_name='coins' then coins+delta else cash+delta end)>=0;
 if not found then raise exception 'wallet missing or balance would become negative'; end if;
 insert into public.wallet_transactions(user_id,currency,amount,reason,source,created_by) values(target_user,currency_name,delta,trim(reason_text),'operator_airdrop',(select auth.uid()));
end; $$;
revoke all on function public.operator_adjust_wallet(uuid,text,bigint,text) from public;
grant execute on function public.operator_adjust_wallet(uuid,text,bigint,text) to authenticated;
